import { View } from 'react-native';
import { SvgXml } from 'react-native-svg';

import { categoryArtXml } from './artXml';

export interface CategoryArtProps {
  /** Category slug; top-level slugs have their own scene. */
  slug: string;
  /** Square size in px (drawn for 64–160). */
  size: number;
  /** For a sub-category: the parent's slug, whose scene is shown. */
  parentSlug?: string;
}

/**
 * Category illustration with Clan characters (generated by `npm run art:build`, see
 * scripts/illustrations). Transparent background so the world's card style shows through;
 * decorative, so hidden from screen readers (the card's title names the category). The a11y
 * props sit on a View: on web `SvgXml` is a plain <svg> and would forward them to the DOM.
 */
export function CategoryArt({ slug, size, parentSlug }: CategoryArtProps) {
  return (
    <View accessibilityElementsHidden importantForAccessibility="no-hide-descendants">
      <SvgXml xml={categoryArtXml(slug, parentSlug)} width={size} height={size} />
    </View>
  );
}
